<?php
require_once __DIR__.'/database.php';
appSessionStart();
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
if(isset($_GET['logout'])){session_unset();session_destroy();header('Location: login.php');exit;}
if(!empty($_SESSION['user_id'])){header('Location: index.php');exit;}
if(empty($_SESSION['login_csrf']))$_SESSION['login_csrf']=bin2hex(random_bytes(32));
$error='';$success='';
try{$pdo=appDatabase();}catch(Throwable $e){http_response_code(503);exit('Вход временно недоступен. Повторите позже.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
if(!hash_equals($_SESSION['login_csrf'],$_POST['csrf']??'')){$error='Обновите страницу и повторите вход.';}
else{
$raw=trim($_POST['phone']??'');$digits=preg_replace('/\D/','',$raw);if(strlen($digits)===11&&$digits[0]==='8')$digits='7'.substr($digits,1);$phone='+'.$digits;$alt='8'.substr($digits,1);$password=$_POST['password']??'';$action=$_POST['action']??'';
if(!preg_match('/^7\d{10}$/',$digits))$error='Введите казахстанский номер: +7 или 8 и ещё 10 цифр.';
elseif($action==='login'){
if(($_SESSION['login_wait']??0)>time()){$error='Слишком много попыток. Подождите минуту.';}else{
$q=$pdo->prepare('SELECT * FROM users WHERE phone IN (?,?,?,?) LIMIT 1');$q->execute([$phone,$digits,$alt,$raw]);$u=$q->fetch();
if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);unset($_SESSION['staff_id'],$_SESSION['staff_role'],$_SESSION['staff_name']);foreach(['user_id'=>'id','user_phone'=>'phone','biz_name'=>'biz_name','biz_category'=>'biz_category','location'=>'location'] as $k=>$v)$_SESSION[$k]=$u[$v];$_SESSION['login_attempts']=0;unset($_SESSION['login_csrf']);session_write_close();header('Location: index.php');exit;}
else{$_SESSION['login_attempts']=($_SESSION['login_attempts']??0)+1;if($_SESSION['login_attempts']>=8){$_SESSION['login_wait']=time()+60;$_SESSION['login_attempts']=0;}$error='Неверный номер телефона или пароль.';}
}
}elseif($action==='register'){
$name=mb_substr(trim($_POST['biz_name']??''),0,180);$category=mb_substr(trim($_POST['biz_category']??'services'),0,60);$location=mb_substr(trim($_POST['location']??'Тараз'),0,100);
if(!$name||mb_strlen($password)<8||mb_strlen($password)>128){$error='Укажите название бизнеса и пароль от 8 до 128 символов.';}else{
$q=$pdo->prepare('SELECT id FROM users WHERE phone IN (?,?,?) LIMIT 1');$q->execute([$phone,$digits,$alt]);if($q->fetch())$error='Этот номер уже зарегистрирован. Войдите в аккаунт.';else{try{$q=$pdo->prepare('INSERT INTO users(phone,password,biz_name,biz_category,location) VALUES(?,?,?,?,?)');$q->execute([$phone,password_hash($password,PASSWORD_DEFAULT),$name,$category,$location]);$success='Аккаунт создан. Войдите с вашим номером и паролем.';}catch(Throwable $e){$error='Не удалось создать аккаунт. Проверьте данные и повторите.';}}
}
}
}
}
