нство'}function togglePassword(id){let e=document.getElementById(id);e.type=e.type==='password'?'text':'password'}function loginLang(l){localStorage.setItem('aulieata.lang',l);document.getElementById('welcome').textContent=l==='kk'?'Қош келдіңіз':'Добро пожаловать';document.getElementById('heading').textContent=l==='kk'?'Жұмыс кеңістігіне кіру':'Вход в пространство';document.getElementById('intro').textContent=l==='kk'?'Бизнесіңізбен жұмысты жалғастырыңыз.':'Продолжите работу с вашим бизнесом.';document.getElementById('enter').textContent=l==='kk'?'Кабинетке кіру ↗':'Войти в кабинет ↗'}<?php if(($_POST['action']??'')==='register'&&$error): ?>switchTab(true);<?php endif; ?></script></body></html>
